// smoke.spec.js — tool-specific checks for File Hash and Checksum Calculator.
// Fixtures: tests/fixtures/sample.txt, abc.txt, empty.txt (generated by tests/make-fixtures.js, fictional text).
const { test, expect } = require('@playwright/test');
const crypto = require('crypto');
const fs = require('fs');
const path = require('path');

const fixture = (name) => path.join(__dirname, 'fixtures', name);
const ALGOS = { 'MD5': 'md5', 'SHA-1': 'sha1', 'SHA-256': 'sha256', 'SHA-384': 'sha384', 'SHA-512': 'sha512' };
const ABC_SHA256 = 'ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad';
const nodeHash = (algo, data) => crypto.createHash(algo).update(data).digest('hex');
const row = (page, algo, card = page.locator('#results .hash-card').first()) => card.locator(`tr[data-algo="${algo}"] .hash-value`);

async function pasteInto(page, selector, text) {
  await page.locator(selector).focus();
  await page.evaluate(([sel, value]) => {
    const dt = new DataTransfer();
    dt.setData('text/plain', value);
    document.querySelector(sel).dispatchEvent(new ClipboardEvent('paste', { clipboardData: dt, bubbles: true, cancelable: true }));
  }, [selector, text]);
}

function rgb(color) { return color.match(/\d+(\.\d+)?/g).slice(0, 3).map(Number); }

test.describe('File Hash and Checksum Calculator', () => {
  test('hashing the text abc gives the standard SHA-256 (native and hand-written code)', async ({ page }) => {
    for (const url of ['./', './?engine=js']) {
      await page.goto(url);
      await expect(page.locator('html')).toHaveAttribute('data-selftest', 'ok');
      await page.click('#tab-text');
      await page.fill('#text-input', 'abc');
      await page.click('#hash-text');
      await expect(row(page, 'sha256')).toHaveText(ABC_SHA256);
      await expect(row(page, 'md5')).toHaveText('900150983cd24fb0d6963f7d28e17f72');
      await expect(row(page, 'sha1')).toHaveText('a9993e364706816aba3e25717850c26c9cd0d89d');
      await expect(row(page, 'sha512')).toHaveText(nodeHash('sha512', 'abc'));
      await expect(page.locator('#results .result__info')).toContainText('3 bytes');
    }
  });

  test('the trailing newline option changes the hashed bytes', async ({ page }) => {
    await page.goto('./');
    await page.click('#tab-text');
    await page.fill('#text-input', 'abc');
    await expect(row(page, 'sha256')).toHaveText(ABC_SHA256);
    await page.check('#text-newline');
    await expect(row(page, 'sha256')).toHaveText(nodeHash('sha256', 'abc\n'));
    await expect(page.locator('#results .result__info')).toContainText('4 bytes');
  });

  test('hashing the bundled sample.txt shows MD5, SHA-1, SHA-256 and SHA-512 together', async ({ page }) => {
    await page.goto('./');
    const data = fs.readFileSync(fixture('sample.txt'));
    await page.setInputFiles('#file-input', fixture('sample.txt'));
    const card = page.locator('#results .hash-card');
    await expect(card).toHaveCount(1);
    await expect(card.locator('.result__name')).toHaveText('sample.txt');
    for (const [label, algo] of Object.entries(ALGOS)) {
      await expect(card.locator(`tr[data-algo="${algo}"] th`)).toHaveText(label);
      await expect(row(page, algo)).toHaveText(nodeHash(algo, data));
      await expect(card.locator(`tr[data-algo="${algo}"] button`)).toHaveText('Copy');
    }
    await expect(page.locator('#progress-wrap')).toBeVisible();
    await expect(page.locator('#progress-pct')).toHaveText('100%');
  });

  test('a correct expected hash shows a green match and a wrong one a red mismatch', async ({ page }) => {
    await page.goto('./');
    const data = fs.readFileSync(fixture('sample.txt'));
    const sha256 = nodeHash('sha256', data);
    await page.setInputFiles('#file-input', fixture('sample.txt'));
    await expect(row(page, 'sha256')).toHaveText(sha256);
    const chip = page.locator('#compare-status');
    await expect(chip).toHaveText('Waiting');

    // Ctrl/Cmd+V of a whole checksum line: the file name is stripped and the comparison runs at once.
    await pasteInto(page, '#expected', `  ${sha256.toUpperCase()}  sample.txt\n`);
    await expect(page.locator('#expected')).toHaveValue(`${sha256.toUpperCase()}  sample.txt`);
    await expect(chip).toHaveAttribute('data-state', 'match');
    await expect(chip).toHaveText('Match');
    await expect(page.locator('#compare-detail')).toContainText('SHA-256 of sample.txt');
    await expect(page.locator('tr.is-match[data-algo="sha256"]')).toHaveCount(1);
    let [r, g] = rgb(await chip.evaluate((el) => getComputedStyle(el).color));
    expect(g, 'match chip is green').toBeGreaterThan(r);

    // MD5 with colons is normalized too, and the matching algorithm is reported.
    const md5 = nodeHash('md5', data).match(/../g).join(':');
    await page.fill('#expected', md5);
    await expect(chip).toHaveAttribute('data-state', 'match');
    await expect(page.locator('#compare-detail')).toContainText('MD5');

    const wrong = sha256.slice(0, -1) + (sha256.endsWith('0') ? '1' : '0');
    await page.fill('#expected', wrong);
    await expect(chip).toHaveAttribute('data-state', 'mismatch');
    await expect(chip).toHaveText('No match');
    await expect(page.locator('#compare-detail')).toContainText('SHA-256');
    [r, g] = rgb(await chip.evaluate((el) => getComputedStyle(el).color));
    expect(r, 'mismatch chip is red').toBeGreaterThan(g);
  });

  test('the uppercase toggle and Base64 output change how hashes are shown', async ({ page }) => {
    await page.goto('./');
    const data = fs.readFileSync(fixture('sample.txt'));
    await page.setInputFiles('#file-input', fixture('sample.txt'));
    const sha256 = nodeHash('sha256', data);
    await expect(row(page, 'sha256')).toHaveText(sha256);
    await page.check('#uppercase');
    await expect(row(page, 'sha256')).toHaveText(sha256.toUpperCase());
    await expect(row(page, 'md5')).toHaveText(nodeHash('md5', data).toUpperCase());
    await page.uncheck('#uppercase');
    await expect(row(page, 'sha256')).toHaveText(sha256);
    await page.selectOption('#format', 'base64');
    await expect(row(page, 'sha256')).toHaveText(crypto.createHash('sha256').update(data).digest('base64'));
    await expect(page.locator('#uppercase')).toBeDisabled();
    await page.fill('#expected', crypto.createHash('sha512').update(data).digest('base64'));
    await expect(page.locator('#compare-status')).toHaveAttribute('data-state', 'match');
  });

  test('a file of several MB shows a progress bar and finishes with correct hashes', async ({ page }) => {
    await page.goto('./?engine=js');
    const size = 13 * 1024 * 1024 + 12345;
    const buffer = Buffer.alloc(size);
    for (let i = 0; i < size; i++) buffer[i] = (i * 2654435761) >>> 24;
    await page.evaluate(() => {
      window.__progress = [];
      const bar = document.getElementById('progress');
      new MutationObserver(() => {
        if (!document.getElementById('progress-wrap').hidden) window.__progress.push(Number(bar.getAttribute('aria-valuenow')));
      }).observe(bar, { attributes: true, attributeFilter: ['aria-valuenow'] });
    });
    await page.setInputFiles('#file-input', { name: 'disk-image.bin', mimeType: 'application/octet-stream', buffer });
    await expect(page.locator('#progress-wrap')).toBeVisible();
    await expect(page.locator('#progress-wrap')).toHaveClass(/is-done/, { timeout: 30_000 });
    await expect(page.locator('#progress-pct')).toHaveText('100%');
    await expect(page.locator('#progress-label')).toContainText('Done');
    const seen = await page.evaluate(() => window.__progress);
    expect(seen.some((p) => p > 0 && p < 100), `intermediate progress values: ${seen}`).toBeTruthy();
    expect(seen.every((p, i) => i === 0 || p >= seen[i - 1] || p === 0)).toBeTruthy();
    for (const algo of Object.values(ALGOS)) await expect(row(page, algo)).toHaveText(nodeHash(algo, buffer));
  });

  test('empty files give the standard empty hashes', async ({ page }) => {
    await page.goto('./');
    await page.setInputFiles('#file-input', fixture('empty.txt'));
    await expect(row(page, 'md5')).toHaveText('d41d8cd98f00b204e9800998ecf8427e');
    await expect(row(page, 'sha256')).toHaveText('e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855');
    await expect(row(page, 'sha1')).toHaveText('da39a3ee5e6b4b0d3255bfef95601890afd80709');
  });

  test('several files download as checksums.txt and hashes.csv', async ({ page }) => {
    await page.goto('./');
    await page.setInputFiles('#file-input', [fixture('sample.txt'), fixture('abc.txt'), fixture('sample.png')]);
    await expect(page.locator('#results .hash-card')).toHaveCount(3);
    await expect(page.locator('#results .hash-card tr[data-algo="sha512"]')).toHaveCount(3);
    await expect(page.locator('#downloads')).toBeVisible();

    const [list] = await Promise.all([page.waitForEvent('download'), page.click('#download-list')]);
    expect(list.suggestedFilename()).toBe('checksums.txt');
    const text = fs.readFileSync(await list.path(), 'utf8');
    const expected = ['sample.txt', 'abc.txt', 'sample.png'].map((n) => `${nodeHash('sha256', fs.readFileSync(fixture(n)))}  ${n}`).join('\n') + '\n';
    expect(text).toBe(expected);

    await page.selectOption('#list-algo', 'md5');
    const [list2] = await Promise.all([page.waitForEvent('download'), page.click('#download-list')]);
    expect(fs.readFileSync(await list2.path(), 'utf8').split('\n')[1]).toBe(`900150983cd24fb0d6963f7d28e17f72  abc.txt`);

    const [csv] = await Promise.all([page.waitForEvent('download'), page.click('#download-csv')]);
    expect(csv.suggestedFilename()).toBe('hashes.csv');
    const lines = fs.readFileSync(await csv.path(), 'utf8').trim().split('\r\n');
    expect(lines[0]).toBe('file,size_bytes,MD5,SHA-1,SHA-256,SHA-384,SHA-512');
    expect(lines).toHaveLength(4);
    expect(lines[2]).toContain(`abc.txt,3,900150983cd24fb0d6963f7d28e17f72,`);
    expect(lines[2]).toContain(ABC_SHA256);
  });

  test('works at 390px wide with results and the compare field visible', async ({ page }) => {
    await page.setViewportSize({ width: 390, height: 844 });
    await page.goto('./');
    await expect(page.locator('#dropzone')).toBeInViewport();
    await page.setInputFiles('#file-input', fixture('sample.txt'));
    await expect(row(page, 'sha512')).toBeVisible();
    await page.fill('#expected', nodeHash('sha512', fs.readFileSync(fixture('sample.txt'))));
    await expect(page.locator('#compare-status')).toHaveAttribute('data-state', 'match');
    const widths = await page.evaluate(() => ({ doc: document.documentElement.scrollWidth, win: window.innerWidth }));
    expect(widths.doc).toBeLessThanOrEqual(widths.win + 1);
    const overflow = await page.evaluate(() => [...document.querySelectorAll('#tool *')]
      .filter((el) => el.getBoundingClientRect().right > window.innerWidth + 1).map((el) => el.className || el.tagName));
    expect(overflow).toEqual([]);
    const copy = page.locator('#results tr[data-algo="sha512"] button');
    await copy.scrollIntoViewIfNeeded();
    await expect(copy).toBeInViewport();
  });

  test('the demo hook shows a finished, matching result', async ({ page }) => {
    await page.goto('./');
    await page.evaluate(() => window.__demo());
    await expect(page.locator('#results .hash-card')).toHaveCount(1);
    await expect(page.locator('#compare-status')).toHaveAttribute('data-state', 'match');
  });
});
